package io.rift.cronos;
import android.content.*;import android.security.keystore.*;import android.util.Base64;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
/** Native-only, single-wallet entropy vault. Requires device-credential authentication; never WebView/export. */
public final class WalletVault {
 private static final Object LOCK=new Object();private static final String ALIAS="rift.wallet.entropy.v1";private final SharedPreferences prefs;
 public WalletVault(Context context){prefs=context.getSharedPreferences("rift.native.wallet",Context.MODE_PRIVATE);}
 private SecretKey key(boolean create)throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(store.containsAlias(ALIAS))return ((KeyStore.SecretKeyEntry)store.getEntry(ALIAS,null)).getSecretKey();if(!create)throw new IllegalStateException("Wallet key unavailable; recover with your phrase on a trusted wallet. No automatic reset.");KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setRandomizedEncryptionRequired(true).setUserAuthenticationRequired(true).setUserAuthenticationValidityDurationSeconds(300).build());return generator.generateKey();}
 public String address()throws Exception{synchronized(LOCK){String raw=prefs.getString("vault",null);return raw==null?"":new JSONObject(raw).getString("address");}}
 public boolean backedUp(){synchronized(LOCK){return prefs.getBoolean("backupConfirmed",false);}}
 private byte[] aad(String address){return (ALIAS+"|"+WalletCrypto.PATH+"|"+address).getBytes(StandardCharsets.UTF_8);}
 public String create(byte[] entropy)throws Exception{synchronized(LOCK){if(prefs.contains("vault"))throw new IllegalStateException("Wallet already exists; never overwrite without explicit authenticated deletion");String address=WalletCrypto.address(entropy);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key(true));cipher.updateAAD(aad(address));JSONObject box=new JSONObject().put("schema",1).put("address",address).put("iv",Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)).put("data",Base64.encodeToString(cipher.doFinal(entropy),Base64.NO_WRAP));if(!prefs.edit().putString("vault",box.toString()).putBoolean("backupConfirmed",false).commit())throw new IllegalStateException("Wallet not saved");return address;}}
 public byte[] unlock()throws Exception{synchronized(LOCK){String raw=prefs.getString("vault",null);if(raw==null)throw new IllegalStateException("No wallet");JSONObject box=new JSONObject(raw);if(box.getInt("schema")!=1)throw new IllegalStateException("Unsupported wallet schema");String address=box.getString("address");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(false),new GCMParameterSpec(128,Base64.decode(box.getString("iv"),Base64.NO_WRAP)));cipher.updateAAD(aad(address));byte[] entropy=cipher.doFinal(Base64.decode(box.getString("data"),Base64.NO_WRAP));try{if(!WalletCrypto.address(entropy).equals(address))throw new GeneralSecurityException("Wallet identity mismatch");return entropy;}catch(Exception e){Arrays.fill(entropy,(byte)0);throw e;}}}
 public void confirmBackup()throws Exception{synchronized(LOCK){byte[] value=unlock();Arrays.fill(value,(byte)0);if(!prefs.edit().putBoolean("backupConfirmed",true).commit())throw new IllegalStateException("Backup confirmation not saved");}}
 public void delete(String expected)throws Exception{synchronized(LOCK){byte[] value=unlock();Arrays.fill(value,(byte)0);if(!address().equals(expected))throw new IllegalStateException("Wallet changed");if(!prefs.edit().clear().commit())throw new IllegalStateException("Wallet not removed");KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);store.deleteEntry(ALIAS);}}
}
